text:
{
  "outline": [
    {
      "title": "极限与连续基础",
      "summary": "介绍数列极限、函数极限、两个重要极限和无穷小量比较，为后续导数与积分打下分析基础。",
      "kc_names": ["极限与连续", "数列极限", "函数极限", "两个重要极限"]
    },
    {
      "title": "导数与微分计算",
      "summary": "学习导数的定义、几何意义、基本初等函数导数表、四则与复合求导法则、高阶导数和隐函数求导，掌握微分运算工具。",
      "kc_names": ["导数", "基本初等函数导数表", "求导法则", "高阶导数"]
    },
    {
      "title": "微分中值定理与洛必达法则",
      "summary": "从罗尔定理到拉格朗日、柯西中值定理，再到洛必达法则，建立函数整体与局部的关系，用于证明和求极限。",
      "kc_names": ["罗尔定理", "拉格朗日中值定理", "柯西中值定理", "洛必达法则"]
    },
    {
      "title": "泰勒公式与近似计算",
      "summary": "学习泰勒多项式、佩亚诺余项和拉格朗日余项，掌握常用函数的麦克劳林展开，用于近似计算和求极限。",
      "kc_names": ["泰勒公式", "麦克劳林展开"]
    },
    {
      "title": "积分学基础与计算",
      "summary": "从不定积分和基本积分表出发，学习换元积分法和分部积分法，再过渡到定积分定义、性质及牛顿-莱布尼茨公式。",
      "kc_names": ["不定积分", "基本积分表", "换元积分法", "分部积分法"]
    },
    {
      "title": "定积分应用",
      "summary": "利用定积分解决几何和物理问题，如面积、体积、弧长等，巩固积分思想。",
      "kc_names": ["定积分", "牛顿-莱布尼茨公式", "定积分的应用"]
    }
  ],
  "glossary": [
    {"term": "极限", "definition": "当自变量趋近某值时，函数值无限接近一个确定的常数，是微积分的基础概念。"},
    {"term": "导数", "definition": "函数在某点的瞬时变化率，几何上表示曲线在该点切线的斜率。"},
    {"term": "微分中值定理", "definition": "一类定理，表明函数在区间上的整体变化与内部某点的导数有关，包括罗尔、拉格朗日和柯西中值定理。"},
    {"term": "泰勒公式", "definition": "用多项式逼近光滑函数的方法，余项控制误差，常用于近似计算和极限分析。"},
    {"term": "不定积分", "definition": "导数的逆运算，求一个函数的原函数族，结果包含任意常数。"},
    {"term": "定积分", "definition": "函数在区间上的累积和极限，几何上表示曲边梯形的面积，由牛顿-莱布尼茨公式计算。"},
    {"term": "洛必达法则", "definition": "求 $\\frac{0}{0}$ 或 $\\frac{\\infty}{\\infty}$ 型极限的方法，对分子分母分别求导后再取极限。"},
    {"term": "隐函数求导", "definition": "对由方程 $F(x,y)=0$ 确定的函数，两边对 $x$ 求导并解出 $y'$ 的方法。"}
  ],
  "suggested_questions": [
    "如何用两个重要极限求 $\\lim_{x \\to 0} \\frac{\\sin x}{x}$？",
    "复合函数求导的链式法则如何应用？举例说明。",
    "拉格朗日中值定理与罗尔定理有什么关系？",
    "如何用泰勒公式近似计算 $e^{0.1}$？",
    "换元积分法与分部积分法分别适用于什么类型的积分？"
  ]
}
